// sketch: recompute LIS for a block
function recomputeBlock(block) {
  const arr = block.values;
  // standard patience algorithm within block
  let tails = [];
  for (const x of arr) {
    let i = tails.findIndex(t => t >= x);
    if (i === -1) tails.push(x); else tails[i] = x;
  }
  block.lisLen = tails.length;
}
```

